      '<div class="pps-pfld"><span class="pl">좌석수</span><span class="pps-pin ' + (ro ? 'ro' : '') + '">' + (ro ? '2 (읽기전용)' : '2') + '</span></div>' +
      '<div class="pps-pfld"><span class="pps-pbtn">예매</span></div>';
