        '<div class="trbody"><span>ok_code 진입=<b>' + (t.inCode ? "'" + esc(t.inCode) + "'" : "''") + '</b></span>' +
        '<span>save_ok=<b>' + (t.saveOk ? "'" + esc(t.saveOk) + "'" : "''") + '</b></span>' +
